      "description": "Source file does not exist - Error case for non-existent source location",
      "test_frame": {
        "Source location": "does not exist",
        "Source file attributes": "regular file"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/tmp/nonexistent_file.txt",
        "destination": "/local/backup_dir/",
        "command": "distributed_file_sync /tmp/nonexistent_file.txt /local/backup_dir/ --source-type local file --no-authentication",
        "expected_error": "File does not exist: /tmp/nonexistent_file.txt"
      }
    },
    {
      "test_id": "TC002",
      "description": "Permission denied - Error case for unauthorized source access",
      "test_frame": {
        "Source location": "permission denied",
        "Source file attributes": "regular file"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/root/private_file.txt",
        "destination": "/local/backup_dir/",
        "command": "distributed_file_sync /root/private_file.txt /local/backup_dir/ --source-type local file --no-authentication",
        "expected_error": "Permission denied accessing file from /root"
      }
    },
    {
      "test_id": "TC003",
      "description": "Invalid destination - Error case for invalid destination specification",
      "test_frame": {
        "Destination location": "invalid destination",
        "Source location": "local file"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/local/file.txt",
        "destination": "nonexistent/path/file.txt",
        "command": "distributed_file_sync /local/file.txt nonexistent/path/file.txt --mode one-way",
        "expected_error": "Invalid destination specification: nonexistent/path/file.txt"
      }
    },
    {
      "test_id": "TC004",
      "description": "Destination unreachable - Error case for unreachable destination",
      "test_frame": {
        "Destination location": "destination unreachable",
        "Source location": "cloud storage (S3)"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "s3://bucket/data/file.txt",
        "destination": "local:/path/unreachable/",
        "command": "distributed_file_sync s3://bucket/data/file.txt local:/path/unreachable/ --mode one-way",
        "expected_error": "Destination unreachable: local:/path/unreachable/"
      }
    },
    {
      "test_id": "TC005",
      "description": "Insufficient disk space - Error case for large file sync",
      "test_frame": {
        "Source file attributes": "huge (>1GB)",
        "System resources": "insufficient disk space",
        "File size category": "huge (>1GB)"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/huge/large_file.bin",
        "destination": "/local/backup/",
        "command": "distributed_file_sync /huge/large_file.bin /local/backup/ --mode one-way --verify sha256",
        "expected_error": "Insufficient disk space: Cannot write to /local/backup/"
      }
    },
    {
      "test_id": "TC006",
      "description": "Destination locked - Error case for locked destination",
      "test_frame": {
        "Destination location": "same as source type",
        "Concurrent operations": "destination locked"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/local/file.txt",
        "destination": "/local/locked_file.txt",
        "command": "distributed_file_sync /local/file.txt /local/locked_file.txt --mode one-way --conflict overwrite",
        "expected_error": "Destination locked: Cannot overwrite existing file"
      }
    },
    {
      "test_id": "TC007",
      "description": "Source locked - Error case for locked source file",
      "test_frame": {
        "Source location": "local file",
        "Concurrent operations": "source locked"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/local/locked_file.txt",
        "destination": "/remote/backup/",
        "command": "distributed_file_sync /local/locked_file.txt /remote/backup/ --mode one-way",
        "expected_error": "Source locked: Cannot access locked file"
      }
    },
    {
      "test_id": "TC008",
      "description": "Merge content conflict - Error case for incompatible sync strategy",
      "test_frame": {
        "Conflict resolution": "merge content",
        "File size category": "small (1KB-1MB)",
        "Destination location": "same as source type"
      },
      "expected_outcome": "error",
      "test_data": {
        "source": "/local/small_file.txt",
        "destination": "/local/backup/small_file.txt",
        "command": "distributed_file_sync /local/small_file.txt /local/backup/small_file.txt --mode one-way --conflict merge content",
        "expected_error": "Merge content is not supported for this file size category. Use skip existing instead."
      }
    },
    {
      "test_id": "TC009",
      "description": "Multi-factor authentication - Single case for enhanced security",
      "test_frame": {
        "Source authentication": "multi-factor authentication",
        "Security context": "trusted network"
      },
      "expected_outcome": "success",
      "test_data": {
        "source": "ssh://user@secure-server.com/file.txt",
        "destination": "/local/backup/",
        "command": "distributed_file_sync ssh://user@secure-server.com/file.txt /local/backup/ --mfa --mode one-way --trust-network",
        "expected_error": null
      }
    },
    {
      "test_id": "TC010",
